/** Authored deterministic quality fixture; not model output or a complete Tetris product. */
export const quality3dFiles:Record<string,string>={
'src/model.ts':`export type Cell={id:string;x:number;y:number;z:number};
export const initialCells:Cell[]=[{id:'one',x:0,y:0,z:0},{id:'two',x:2,y:3,z:1}];
export function advance(cells:Cell[]):Cell[]{const id=cells.length;return [...cells,{id:String(id),x:id%4,y:Math.floor(id/4),z:id%2}]}
`,
'src/components/Scene.tsx':`import type{Cell}from'../model';
export function Scene({cells,angle,x}:{cells:Cell[];angle:number;x:number}){return <div data-testid="board" className="board" tabIndex={0}><div data-testid="camera" className="camera" style={{transform:'rotateX(-15deg) rotateY('+angle+'deg)'}}>{cells.map(c=><div role="listitem" aria-label="Block" data-testid="cube" data-x={c.x} data-y={c.y} data-z={c.z} key={c.id} className="cube" style={{transform:'translate3d('+c.x*24+'px,'+c.y*24+'px,'+c.z*24+'px)'}}>{[0,1,2,3,4,5].map(f=><div key={f} className={'face f'+f}/>)}</div>)}<div data-testid="actor" className="actor" style={{transform:'translateX('+x*24+'px)'}}/></div></div>}
`,
'src/components/Controls.tsx':`export function Controls({auto,paused,setAuto,setPaused,rotate,restart}:{auto:boolean;paused:boolean;setAuto:(v:boolean)=>void;setPaused:(v:boolean)=>void;rotate:()=>void;restart:()=>void}){return <section><label><input aria-label="Automatic control" type="checkbox" checked={auto} onChange={e=>setAuto(e.target.checked)}/>Automatic control</label><button onClick={()=>setPaused(!paused)}>{paused?'Resume':'Pause'}</button><button onClick={rotate}>Rotate view</button><button onClick={restart}>Restart</button></section>}
`,
'src/App.tsx':`import{useEffect,useState}from'react';import{initialCells,advance}from'./model';import{Scene}from'./components/Scene';import{Controls}from'./components/Controls';
export default function App(){const[cells,setCells]=useState(initialCells);const[auto,setAuto]=useState(false);const[paused,setPaused]=useState(false);const[angle,setAngle]=useState(20);const[x,setX]=useState(2);useEffect(()=>{if(!auto||paused)return;const timer=setInterval(()=>{setCells(c=>advance(c));setX(p=>p+1)},500);return()=>clearInterval(timer)},[auto,paused]);useEffect(()=>{const key=(e:KeyboardEvent)=>{if(!auto&&!paused&&e.key==='ArrowLeft')setX(p=>p-1)};window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key)},[auto,paused]);return <main><h1>Explicit authored 3D fixture</h1><Controls auto={auto} paused={paused} setAuto={setAuto} setPaused={setPaused} rotate={()=>setAngle(a=>a+35)} restart={()=>{setCells(initialCells);setX(2)}}/><Scene cells={cells} angle={angle} x={x}/><output data-testid="value">{cells.length}</output></main>}
`,
'src/style.css':`body{margin:0;font-family:system-ui}.board{perspective:700px;width:500px;height:400px;margin:40px;position:relative}.camera{transform-style:preserve-3d;transform-origin:150px 100px;width:400px;height:300px;position:relative}.cube{position:absolute;left:50px;top:50px;width:20px;height:20px;transform-style:preserve-3d}.face{position:absolute;width:20px;height:20px;background:#2979d5;border:1px solid #123;opacity:.8;backface-visibility:visible}.f0{transform:translateZ(10px)}.f1{transform:rotateY(180deg) translateZ(10px)}.f2{transform:rotateY(90deg) translateZ(10px)}.f3{transform:rotateY(-90deg) translateZ(10px)}.f4{transform:rotateX(90deg) translateZ(10px)}.f5{transform:rotateX(-90deg) translateZ(10px)}.actor{position:absolute;left:20px;top:220px;width:20px;height:20px;background:#f90}button{padding:10px;margin:4px}`,
};
